import Mathlib

open Filter Finset Real

def setA : Set ℕ := {n | ∀ d ∈ Nat.digits 3 n, d ≤ 1}
def setB : Set ℕ := {n | ∀ d ∈ Nat.digits 4 n, d ≤ 1}
def setAB : Set ℕ := {n | ∃ a ∈ setA, ∃ b ∈ setB, a + b = n}

theorem erdos_125 : ∃ n : ℕ, n ∉ setAB := by
  use 62
  intro ⟨a, ha, b, hb, hab⟩
  simp only [setA, setB, Set.mem_setOf] at ha hb
  have ha_eq : a = 62 - b := by omega
  rw [ha_eq] at ha
  have hb_le : b ≤ 62 := by omega

  -- Case split on all possible values of b
  interval_cases b <;> {
    -- For b ∉ setB (most cases), simp [Nat.digits] should derive contradiction from hb
    simp only [Nat.digits] at hb
    -- For the 8 cases where b ∈ setB, use the digit constraint on ha
    try { simp only [Nat.digits] at ha; norm_num at ha; omega }
    try { omega }
  }

